function Safe:ctor(family_id, roleType, parent, curPoint)
    ReqMgr:addHandle("Safe", EVENTNAME)

    --add by zzy 
    self.parent = parent
    --部分适配修复
    SCREEN_WIDTH = cc.Director:getInstance():getOpenGLView():getDesignResolutionSize().width
    SCREEN_HEIGHT = cc.Director:getInstance():getOpenGLView():getDesignResolutionSize().height


    local csbPath = "hall/res/FriendScircle/Safe.csb"
    Safe.super.ctor(self, csbPath)

    self._eventHandles = {}
    self.pageCount = 1
    self._pageIdx = 1
    self.family_id = tonumber(family_id)
    self.roleType = tonumber(roleType)
    self.owerId = owerId
    self.data = {}
    self:InitGame(family_id, roleType)
    self.curPoint = curPoint or 0
    self:initEvent()

    if isHideShowBons4Agent then
        self.txt_11:setVisible(false)
        self.Text_2_0_0:setVisible(false)
    end
end

function Safe:handleRepositoryHandleHistory(event)

    local netData = event.netData
	local param = event.param
	local data = netData.data
    if netData.returnCode == 0 then
        dump(netData.data,"保险柜-----------------------------------"..(self.roleType or "file is safe,line 58, roleType is nil"))
        if self.roleType == 0 then -- 盟主
            self:setData(netData.data)
        elseif self.roleType == 2 then-- 合伙人
            self:setData_1(netData.data)
            self:RequestCludScore()
        elseif self.roleType == 3 then-- 普通玩家
            self:RequestCludScore()
            self:setData_2(netData.data)
        end
    end
end

function Safe:RequestCludScore()
    local data = {
        uid = USER_INFO["uid"] ,
        groupId = self.family_id ,
    }
    ReqMgr:request(EVENTNAME.GOTO_CLUB, data, handler(self , self.goto_club))
end

function Safe:goto_club( event )
    local netData = event.netData
    local param = event.param
    local returnCode = netData.returnCode
    local data = netData.data
    local error = netData.error
    if netData.returnCode == 0 and self and self.txt_12 then
        self.curPoint = data.point / 100
        self.txt_12:setString(self.curPoint)--当前积分：
        self.parent:updateUserScore(data.point)
    end
end

function Safe:handleHeHuoRenTixian(event)
    dump(event,"handleHeHuoRenTixian - event")
    local netData = event.netData
    local param = event.param
    local returnCode = netData.returnCode
    local data = netData.data
    local error = netData.error
    if netData.returnCode == 0 and not tolua.isnull(self) then
        viewMgr:showTip({text = "操作成功"})
        self:InitGame(self.family_id, self.roleType)
    else
        viewMgr:showTip({text = "操作失败"})
    end
end

function Safe:initEvent()
    if isHideStrongboxCunChu then
        self.btn_add_1:setVisible(false)
        self.btn_add_2:setVisible(false)
    else
        self.btn_add_1:onClick(handler(self, self.onClickAdd), true)--储存
        self.btn_add_2:onClick(handler(self, self.onClickAdd), true)--储存
    end
    self.btn_del_1:onClick(handler(self, self.onClickDel), true)--提 取
    self.btn_del_2:onClick(handler(self, self.onClickDel), true)--提 取
end

function Safe:onClickAdd()
    local tip = "当前积分："..self.curPoint
    local AddNumber = AddNumber.new(handler(self, self.addNumberCallback), {intType = 1, tip = tip, curPoint = self.curPoint})
    self:addChild(AddNumber,9999)
end

function Safe:onClickDel()
    local tip = "当前积分："..self.curPoint
    local AddNumber = AddNumber.new(handler(self, self.addNumberCallback), {intType = -1, tip = tip})
    self:addChild(AddNumber,9999)
end

function Safe:addNumberCallback(data)
    local profitOwnerPoint = data.number or 0
    if profitOwnerPoint == 0 then
        viewMgr:showTip({text = "操作失败"})
        return
    end
    profitOwnerPoint = profitOwnerPoint * data.intType
    profitOwnerPoint = tonumber(profitOwnerPoint)*100
    local parma = {}
    if profitOwnerPoint > 0 then
        parma.url = EVENTNAME.SAVE_POINT2_REPOSITORY
        parma.tbl = {
            ["playerId"] = USER_INFO["uid"],
            ["groupId"] = self.family_id,
            ["savePoint"] = profitOwnerPoint,
        }
    else
        parma.url = EVENTNAME.HEHUOREN_TIXIAN
        profitOwnerPoint = profitOwnerPoint * -1
        parma.tbl = {
            ["playerId"] = USER_INFO["uid"],
            ["groupId"] = self.family_id,
            ["tixianCount"] = profitOwnerPoint,
        }
    end
    ReqMgr:request(parma.url, parma.tbl, handler(self , self.handleHeHuoRenTixian))
   
end

