-- 盟主
function Safe:setData(data)
    dump(data,"盟主保险柜-----------------------------------")
    self.data = data
    local pointPool = tonumber(data.pointPool or "0") / 100
    local profitPoint = tonumber(data.profitPoint or "0") / 100
    local maxPoint = tonumber(data.maxPoint or "0") / 100
    self.PageView:removeAllPages()
    self.txt_1:setString(maxPoint)--总积分：
    self.txt_2:setString(pointPool)--积分池：
    self.txt_4:setString(profitPoint)--剩余所有未提取积分(包括合伙人maxPoint)：
    self.txt_3:setString((data.maxPoint - data.profitPoint - data.pointPool)/100)--当前可使用积分：
    self.txt_5:setString(data.xiaohaoYesterday / 100)--昨日积分消耗：
    self.txt_6:setString(data.profitOwnerPoint / 100)--剩余未提取积分：
    self.txt_7:setString(data.xiaohaoToday / 100)--今日积分消耗：
    self.txt_14:setString(data.ClubBaiRenPool / 100)--百人场
    self.txt_15:setString(data.ClubBaiRenPool / 100)--百人场消耗：

    local list = #data.list
    local num = 4 -- 1页有四条数据
    local layous = {}
    local page_height = self.PageView:getContentSize().height
    local item_height = self.item:getContentSize().height
    self.pageCount = math.ceil(list / num)
    for i = 1, self.pageCount do 
        local layout = ccui.Layout:create()
        self.PageView:addPage(layout)
        layous[i] = layout
    end

    for index, data in ipairs(data.list) do
        local layouIndex = math.ceil(index / num)
        local layout = layous[layouIndex]
        local item = self.item:clone()
        GameUtils.setNodeNameBindObj(item)
        layout:addChild(item)
        local itemIdx = math.ceil(index % num)
        if itemIdx == 0 then itemIdx = num end
        local x = page_height - (item_height * itemIdx + ((itemIdx-1) * 10) )
        item:setVisible(true)
        item:setPosition(cc.p(0, x))
        local time_str = os.date("%Y-%m-%d %H:%M:%S", data.createTime/1000)
        item.id:setString(data.playerId)
        local point = data.point / 100
        if data.type == 0 then
            item.Text_19_1:setString("提取积分：")
        elseif data.type == 1 then
            item.Text_19_1:setString("存储积分：")
        elseif data.type == 2 then
            item.Text_19_1:setString("提取百人场池：")
        end
        item.score:setString(point)
        item.time:setString(time_str)
    end
    self:initPageIdx(1)
end
-- 合伙人
function Safe:setData_1(data)
    dump(data,"合伙人保险柜-----------------------------------")
    self.data = data
    
    self.txt_8:setString(data.xiaohaoYesterday / 100)   --昨日消耗
    self.txt_9:setString(data.repositoryPoint / 100)   --保险箱余额
    self.txt_10:setString(data.xiaohaoToday / 100)  --今日消耗
    self.txt_11:setString(data.bonus.."%")  --分成比例
    self.ListView_1:removeAllItems()

    for index, data in ipairs(data.list) do
        local item = self.item:clone()
        GameUtils.setNodeNameBindObj(item)
        self.ListView_1:pushBackCustomItem(item)
        item:setVisible(true)
        local time_str = os.date("%Y-%m-%d %H:%M:%S",data.createTime/1000)
        item.id:setString(data.playerId)
        item.time:setString(time_str)
        local point = data.point / 100
        if data.type == 0 then
            item.Text_19_1:setString("提取积分：")
        elseif data.type == 1 then
            item.Text_19_1:setString("存储积分：")
        elseif data.type == 2 then
            item.Text_19_1:setString("提取百人场池：")
        end
        item.score:setString(point)
    end
end
