function Safe:onClickBtnReturn()
    self:removeSelf()
end

function Safe:onClickBtnExtract(sender)
    if not (self.data and self.data.profitOwnerPoint) then 
        return
    end
    local profitOwnerPoint = math.floor(self.data.profitOwnerPoint/100)
    if profitOwnerPoint > 0 then
        local parma = {}
        parma.url = "/heHuoRenTixian"
        parma.tbl = {
            ["playerId"] = USER_INFO["uid"],
            ["groupId"] = self.family_id,
            ["tixianCount"] = profitOwnerPoint*100,
        }
        ReqMgr:request(EVENTNAME.HEHUOREN_TIXIAN, parma.tbl, handler(self , self.handleHeHuoRenTixian))
    else
        viewMgr:showTip({text = "没有可以提取的分"})
    end
end

-- 左翻页
function Safe:onClickBtn_l(event)
    self:setPageByIdx(self._pageIdx - 1)
end

-- 右翻页
function Safe:onClickBtn_r(event)
    self:setPageByIdx(self._pageIdx + 1)
end
function Safe:setPageByIdx(idx)
    if idx > self.pageCount or idx < 1 then
        return
    end
    self._pageIdx = idx
    self.PageView:setCurrentPageIndex(self._pageIdx - 1)
    dump(self.PageView:getCurrentPageIndex())
    self.txt_page:setString(self._pageIdx.."/"..self.pageCount)

end

function Safe:initPageIdx(idx)
    self:setPageByIdx(idx)
end

function Safe:initBaiRenUI()
    local height = self.member_item:getContentSize().height
    local height2 = self.Panel_2_item:getContentSize().height
    if isShowBaiRen then
        self.Panel_2_item:setVisible(true)
        self.Panel_1_item:setPositionY(height*0.5 + height2*0.5)
        self.Panel_2_item:setPositionY(height*0.5 - height2*0.5)
    else
        self.Panel_2_item:setVisible(false)
        self.Panel_1_item:setPositionY(height*0.5)
        self.Panel_1_item:getChildByName("btnExtract"):setScale(1)
        self.Text_2_154:setVisible(false)
        self.txt_14:setVisible(false)
    end
end

function Safe:onClickBtnExtractBairen(sender)
    if not (self.data and self.data.ClubBaiRenPool) then 
        return
    end
    local ClubBaiRenPool = math.floor(self.data.ClubBaiRenPool/100)
    if ClubBaiRenPool > 0 then

        local tip = "当前百人场池："..ClubBaiRenPool
        local AddNumber = AddNumber.new(handler(self, self.addBaiRenCallback), {intType = 1, tip = tip, curPoint = ClubBaiRenPool})
        self:addChild(AddNumber,9999)

    else
        viewMgr:showTip({text = "没有可以提取的分"})
    end
end

function Safe:addBaiRenCallback(data)

    local ClubBaiRenPool = data.number
    if ClubBaiRenPool == 0 then
        viewMgr:showTip({text = "操作失败"})
        return
    end
    ClubBaiRenPool = tonumber(ClubBaiRenPool)*100

    local parma = {}

    parma.url = EVENTNAME.BAIRENPOOL_TIXIAN
    parma.tbl = {
        ["playerId"] = USER_INFO["uid"],
        ["groupId"] = self.family_id,
        ["tixianCount"] = ClubBaiRenPool,
    }

    ReqMgr:request(parma.url, parma.tbl, handler(self , self.handleHeHuoRenTixian))
   
end

return Safe